import concurrent.futures,hashlib,json,os,shutil,subprocess,sys,time,uuid
from pathlib import Path
ROOT=Path('$WORKSPACE')
BASE=Path('$EVAL')
RUNNER=ROOT/'tests/fixtures/qa-practical/runner.mjs'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def invoke(cmd,folder,prompt,phase):
 start=time.time()
 with (folder/f'{phase}.jsonl').open('w') as out,(folder/f'{phase}.stderr').open('w') as err:
  try:r=subprocess.run(cmd,input=prompt,text=True,cwd=folder/'task',stdout=out,stderr=err,timeout=480);rc=r.returncode
  except subprocess.TimeoutExpired:rc=124
 return {'command':cmd,'exit':rc,'seconds':round(time.time()-start,2)}
def run(cell):
 family,variant,version,mode=cell;name='-'.join(cell);folder=BASE/'runs-v3'/uuid.uuid4().hex[:12];task=folder/'task'
 folder.mkdir(parents=True,exist_ok=False)
 prepared=json.loads(subprocess.check_output(['node',str(RUNNER),'prepare','--family',family,'--variant',variant,'--out',str(task),'--meta',str(folder/'private.json')],text=True,cwd=ROOT))
 skill=task/'.agents/skills/verification-before-completion';shutil.copytree(BASE/version,skill)
 (task/'AGENTS.md').write_text('This is an isolated, already-approved local QA and repair task. Follow TASK.md. Only its allowed files may change; result.json and new test/*.test.mjs files are allowed. Instructions and skill resources are read-only. Do not read parent folders, other tasks, evaluator files, user secrets, or consumer projects. Do not use network, install dependencies, delegate, commit, publish, or change global settings. Use the existing Node and npm tools. Do not ask the user to supply the defect or run tests.\n')
 protected={str(p.relative_to(task)):sha(p) for p in [task/'AGENTS.md',*(task/'.agents').rglob('*')] if p.is_file()}
 prompt=(task/'TASK.md').read_text()
 if mode=='explicit':prompt='Use the repo-local .agents/skills/verification-before-completion/SKILL.md as the completion contract for this already-authorized QA/repair task.\n'+prompt
 (folder/'prompt.txt').write_text(prompt)
 common=['codex','exec','-m','gpt-6-sol','-c','model_reasoning_effort="high"','-s','workspace-write','--skip-git-repo-check']
 first=invoke(common+['-C',str(task),'--json','-o',str(folder/'response1.txt'),'-'],folder,prompt,'turn1')
 events=[]
 for line in (folder/'turn1.jsonl').read_text().splitlines():
  try:events.append(json.loads(line))
  except json.JSONDecodeError:pass
 thread=next((e.get('thread_id') for e in events if e.get('type')=='thread.started'),None)
 first_grade_cmd=subprocess.run(['node',str(RUNNER),'grade','--meta',str(folder/'private.json'),'--workdir',str(task),'--response',str(folder/'response1.txt')],text=True,capture_output=True,cwd=ROOT)
 first_grade=json.loads(first_grade_cmd.stdout)
 kind={'blocks':'wording','sequence':'environment','retry':'flaky'}.get(family) if variant=='healthy' else None
 supplementary=None
 prior_files={}
 followup_prompt=Path(prepared['followupPromptPath']).read_text()
 if kind and first['exit']==0 and thread:
  prior_files={str(p.relative_to(task)):sha(p) for p in task.rglob('*') if p.is_file()}
  extra=json.loads(subprocess.check_output(['node',str(RUNNER),'followup','--kind',kind,'--out',str(task/'followup'),'--meta',str(folder/'followup-private.json')],text=True,cwd=ROOT))
  followup_prompt=Path(extra['promptPath']).read_text()
 second=None
 if first['exit']==0 and thread:
  second=invoke(['codex','exec','-C',str(task),'-s','workspace-write','resume','-m','gpt-6-sol','-c','model_reasoning_effort="high"','--skip-git-repo-check','--json','-o',str(folder/'response2.txt'),thread,'-'],folder,followup_prompt,'turn2')
 current_protected={str(p.relative_to(task)):sha(p) for p in [task/'AGENTS.md',*(task/'.agents').rglob('*')] if p.is_file()}
 protected_ok=current_protected==protected
 grade=subprocess.run(['node',str(RUNNER),'grade','--meta',str(folder/'private.json'),'--workdir',str(task),'--response',str(folder/'response2.txt')],text=True,capture_output=True,cwd=ROOT)
 try:g=json.loads(grade.stdout)
 except json.JSONDecodeError:g={'pass':False,'error':grade.stderr}
 if kind and prior_files:
  fgrade=subprocess.run(['node',str(RUNNER),'grade-followup','--meta',str(folder/'followup-private.json'),'--workdir',str(task)],text=True,capture_output=True,cwd=ROOT)
  fg=json.loads(fgrade.stdout)
  current_files={str(p.relative_to(task)):sha(p) for p in task.rglob('*') if p.is_file() and not str(p.relative_to(task)).startswith('followup/')}
  supplementary={'kind':kind,'grade':fg,'previousFilesPreserved':current_files==prior_files}
  g=first_grade
 result={'name':name,'family':family,'variant':variant,'version':version,'entry':mode,'thread':thread,'turn1':first,'turn2':second,'protectedFiles':protected,'protectedPreserved':protected_ok,'firstGrade':first_grade,'grade':g,'supplementary':supplementary}
 (folder/'result.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
 print(name, 'PASS' if g.get('pass') and protected_ok and (not supplementary or (supplementary['grade'].get('pass') and supplementary['previousFilesPreserved'])) else 'FAIL', 'seconds',round(first['seconds']+(second or {}).get('seconds',0),1),flush=True)
 return result
cells=[(f,v,c,m) for f in sys.argv[1:] for v in ['defect','healthy'] for m in (['explicit'] if f=='blocks' else ['explicit','natural']) for c in ['baseline','candidate']]
summary=[]
with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
 for i in range(0,len(cells),2):
  results=list(pool.map(run,cells[i:i+2]));summary+=results
  (BASE/('batch-'+'-'.join(sys.argv[1:])+'.json')).write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n')
  if any(r['turn1']['exit'] or not r['turn2'] or r['turn2']['exit'] for r in results):
   print('STOP: runtime failure; inspect evidence before retry',flush=True);break
print('FINISHED',len(summary),'task sessions',flush=True)

