export function chargeCents(minutes) {
  if (!Number.isInteger(minutes) || minutes < 0) throw new RangeError('minutes');
  return Math.min(1200, Math.ceil(minutes / 15) * 175);
}
import test from 'node:test';
import assert from 'node:assert/strict';
import { chargeCents } from '../src/charge.mjs';

test('charges each started 15-minute block and caps the day at 1200 cents', () => {
  for (const [minutes, cents] of [
    [0, 0],
    [1, 175],
    [15, 175],
    [16, 350],
    [30, 350],
    [31, 525],
    [90, 1050],
    [91, 1200],
    [105, 1200],
    [106, 1200],
  ]) {
    assert.equal(chargeCents(minutes), cents, `${minutes} minutes`);
  }
});

test('rejects negative and non-integer minutes', () => {
  for (const minutes of [-1, -0.5, 0.5, 15.5, Infinity, NaN]) {
    assert.throws(() => chargeCents(minutes), RangeError, `${minutes} minutes`);
  }
});
