import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, readFileSync, rmSync, writeFileSync, existsSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { publish } from '../src/service.mjs';

function withStore(check) {
  const dir = mkdtempSync(join(tmpdir(), 'publication-test-'));
  try {
    check(join(dir, 'events.jsonl'));
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

test('unapproved first attempt leaves an existing store unchanged', () => {
  withStore(store => {
    const original = '{"id":"existing"}\n';
    writeFileSync(store, original);

    const published = publish(store, { id: 'blocked', approved: false }, 1);
    assert.equal(readFileSync(store, 'utf8'), original);
    assert.equal(published, false);
  });
});

test('unapproved retry does not create a store', () => {
  withStore(store => {
    const published = publish(store, { id: 'blocked', approved: false }, 2);
    assert.equal(existsSync(store), false);
    assert.equal(published, false);
  });
});

test('truthy nonboolean approval leaves the store unchanged', () => {
  withStore(store => {
    const original = '{"id":"existing"}\n';
    writeFileSync(store, original);

    const published = publish(store, { id: 'blocked', approved: 'true' }, 1);
    assert.equal(readFileSync(store, 'utf8'), original);
    assert.equal(published, false);
  });
});

for (const attempt of [1, 2]) {
  test(`approved attempt ${attempt} appends exactly one JSON event`, () => {
    withStore(store => {
      const original = '{"id":"existing"}\n';
      writeFileSync(store, original);

      assert.equal(publish(store, { id: 'allowed', approved: true }, attempt), true);
      const content = readFileSync(store, 'utf8');
      assert.equal(content, original + '{"id":"allowed"}\n');
      assert.deepEqual(content.trimEnd().split('\n').map(JSON.parse), [
        { id: 'existing' },
        { id: 'allowed' },
      ]);
    });
  });
}

