import test from 'node:test';
import assert from 'node:assert/strict';
import { existsSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { publish } from '../src/service.mjs';

test('approved calls append exactly one JSON event each, including retries', () => {
  const dir = mkdtempSync(join(tmpdir(), 'publish-approved-'));
  const storePath = join(dir, 'events.jsonl');
  try {
    for (const attempt of [1, 2, 3]) {
      assert.equal(publish(storePath, { id: `item-${attempt}`, approved: true }, attempt), true);
      const contents = readFileSync(storePath, 'utf8');
      const lines = contents.trimEnd().split('\n');
      assert.equal(lines.length, attempt);
      assert.deepEqual(lines.map(JSON.parse),
        Array.from({ length: attempt }, (_, index) => ({ id: `item-${index + 1}` })));
      assert.equal(contents, lines.join('\n') + '\n');
    }
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test('unapproved calls do not create a missing store', () => {
  const dir = mkdtempSync(join(tmpdir(), 'publish-missing-'));
  const storePath = join(dir, 'events.jsonl');
  try {
    for (const attempt of [1, 2, 3]) {
      assert.equal(publish(storePath, { id: 'rejected', approved: false }, attempt), false);
      assert.equal(existsSync(storePath), false);
    }
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test('unapproved calls leave an existing store unchanged on every attempt', () => {
  const dir = mkdtempSync(join(tmpdir(), 'publish-unapproved-'));
  const storePath = join(dir, 'events.jsonl');
  const original = '{"id":"existing"}\n';
  try {
    writeFileSync(storePath, original);
    for (const approved of [false, undefined, 1, 'true']) {
      for (const attempt of [1, 2, 3]) {
        assert.equal(publish(storePath, { id: 'rejected', approved }, attempt), false);
        assert.equal(readFileSync(storePath, 'utf8'), original);
      }
    }
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

