test('approved calls each append exactly one JSON event, including retries', () => {
  const directory = mkdtempSync(join(tmpdir(), 'publish-'));
  try {
    const storePath = join(directory, 'events.jsonl');
    const existing = '{"id":"existing"}\n';
    writeFileSync(storePath, existing);

    assert.equal(publish(storePath, { id: 'first', approved: true }, 1), true);
    assert.equal(readFileSync(storePath, 'utf8'), existing + '{"id":"first"}\n');

    assert.equal(publish(storePath, { id: 'retry', approved: true }, 2), true);
    const lines = readFileSync(storePath, 'utf8').trimEnd().split('\n');
    assert.deepEqual(lines.map((line) => JSON.parse(line)), [
      { id: 'existing' },
      { id: 'first' },
      { id: 'retry' },
    ]);
  } finally {
    rmSync(directory, { recursive: true, force: true });
  }
});

test('unapproved calls leave an existing store unchanged at every retry', () => {
  const directory = mkdtempSync(join(tmpdir(), 'publish-'));
  try {
    const storePath = join(directory, 'events.jsonl');
    const existing = '{"id":"existing"}\n';
    writeFileSync(storePath, existing);

    for (const attempt of [1, 2, 10]) {
      for (const approved of [false, undefined, null, 0, 'true']) {
        assert.equal(publish(storePath, { id: `${attempt}-${approved}`, approved }, attempt), false);
        assert.equal(readFileSync(storePath, 'utf8'), existing);
      }
    }
  } finally {
    rmSync(directory, { recursive: true, force: true });
  }
});

test('unapproved calls do not create a missing store', () => {
  const directory = mkdtempSync(join(tmpdir(), 'publish-'));
  try {
    const storePath = join(directory, 'events.jsonl');
    assert.equal(publish(storePath, { id: 'blocked', approved: false }, 2), false);
    assert.equal(existsSync(storePath), false);
  } finally {
    rmSync(directory, { recursive: true, force: true });
  }
});

