import test from 'node:test';
import assert from 'node:assert/strict';
import { existsSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { publish } from '../src/service.mjs';

function storeFor(t) {
  const directory = mkdtempSync(join(tmpdir(), 'publication-gate-'));
  t.after(() => rmSync(directory, { recursive: true, force: true }));
  return join(directory, 'events.jsonl');
}

for (const attempt of [1, 2, 10]) {
  test(`unapproved item leaves an existing store unchanged on attempt ${attempt}`, (t) => {
    const store = storeFor(t);
    const original = '{"id":"existing"}\n';
    writeFileSync(store, original);

    assert.equal(publish(store, { id: 'rejected', approved: false }, attempt), false);
    assert.equal(readFileSync(store, 'utf8'), original);
  });
}

test('unapproved item does not create a store', (t) => {
  const store = storeFor(t);

  assert.equal(publish(store, { id: 'rejected', approved: false }, 2), false);
  assert.equal(existsSync(store), false);
});

test('approval must be the boolean true', (t) => {
  const store = storeFor(t);

  for (const approved of [undefined, null, 1, 'true']) {
    assert.equal(publish(store, { id: 'rejected', approved }, 3), false);
  }
  assert.equal(existsSync(store), false);
});

