    const store = storeFor(t);
    const original = '{"id":"existing"}\n';
    writeFileSync(store, original);

    assert.equal(publish(store, { id: 'accepted', approved: true }, attempt), true);
    const contents = readFileSync(store, 'utf8');
    assert.equal(contents, original + '{"id":"accepted"}\n');
    assert.deepEqual(contents.trimEnd().split('\n').map(JSON.parse), [
      { id: 'existing' },
      { id: 'accepted' },
    ]);
  });
}

