import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, readFileSync, rmSync, writeFileSync, existsSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { publish } from '../src/service.mjs';

test('unapproved calls leave an existing store unchanged on every retry', () => {
  const dir = mkdtempSync(join(tmpdir(), 'publish-'));
  try {
    const store = join(dir, 'events.jsonl');
    const original = '{"id":"existing"}\n';
    writeFileSync(store, original);

    for (const approved of [false, 1, 'true', undefined, null]) {
      for (const attempt of [1, 2, 100]) {
        assert.equal(publish(store, { id: `rejected-${attempt}`, approved }, attempt), false);
        assert.equal(readFileSync(store, 'utf8'), original);
      }
    }
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test('unapproved call does not create a store', () => {
  const dir = mkdtempSync(join(tmpdir(), 'publish-'));
  try {
    const store = join(dir, 'events.jsonl');
    assert.equal(publish(store, { id: 'rejected', approved: false }, 2), false);
    assert.equal(existsSync(store), false);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test('each approved call appends exactly one JSON event across attempts', () => {
  const dir = mkdtempSync(join(tmpdir(), 'publish-'));
  try {
    const store = join(dir, 'events.jsonl');
    writeFileSync(store, '{"id":"existing"}\n');
    const expected = [{ id: 'existing' }];
    for (const attempt of [1, 2, 100]) {
      assert.equal(publish(store, { id: `approved-${attempt}`, approved: true }, attempt), true);
      expected.push({ id: `approved-${attempt}` });
      const lines = readFileSync(store, 'utf8').trimEnd().split('\n');
      assert.deepEqual(lines.map((line) => JSON.parse(line)), expected);
      assert.equal(lines.length, expected.length);
    }
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

