import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { publish } from '../src/service.mjs';

test('each approved call appends one parseable JSON event on initial and retry attempts', (t) => {
  const dir = mkdtempSync(join(tmpdir(), 'publish-'));
  t.after(() => rmSync(dir, { recursive: true, force: true }));
  const storePath = join(dir, 'store.jsonl');
  writeFileSync(storePath, '{"id":"previous"}\n');

  assert.equal(publish(storePath, { id: 'approved-1', approved: true }, 1), true);
  let events = readFileSync(storePath, 'utf8').trimEnd().split('\n').map(JSON.parse);
  assert.deepEqual(events, [{ id: 'previous' }, { id: 'approved-1' }]);

  assert.equal(publish(storePath, { id: 'approved-2', approved: true }, 2), true);
  events = readFileSync(storePath, 'utf8').trimEnd().split('\n').map(JSON.parse);
  assert.deepEqual(events, [{ id: 'previous' }, { id: 'approved-1' }, { id: 'approved-2' }]);
});

test('unapproved calls leave the store unchanged on initial and retry attempts', (t) => {
  const dir = mkdtempSync(join(tmpdir(), 'publish-'));
  t.after(() => rmSync(dir, { recursive: true, force: true }));
  const storePath = join(dir, 'store.jsonl');
  const original = '{"id":"previous"}\n';
  writeFileSync(storePath, original);

  for (const approved of [false, undefined, 1]) {
    for (const attempt of [1, 2]) {
      assert.equal(publish(storePath, { id: 'denied', approved }, attempt), false);
      assert.equal(readFileSync(storePath, 'utf8'), original);
    }
  }
});

